from pathlib import Path
import json
R=Path(__file__).resolve().parent
style='Hand-painted cel-shaded 2D medieval Serbian epic fantasy game art, rich warm gold highlights and teal shadows, crisp material texture, same style as reference image. '
geometry='SIDE ELEVATION / LONGITUDINAL CUTAWAY of a gatehouse for a side-scrolling game: the road travels horizontally WEST TO EAST, from LEFT to RIGHT through the passage. It does NOT travel into the picture. Show the SIDE of the vaulted gate tunnel, not a front-facing doorway or decorative facade. Two thick structural supports at left and right, overhead arch/beam, narrow center opening. Invisible walking line at the BOTTOM of 1024x1024 canvas. Do NOT draw ground or a road slab. Center clear opening should span x=384 to640, with underside of arch near y=560; at least 440 pixels of clear height to bottom. Everything in the open passage is TRUE TRANSPARENT, no back wall, no scenery. Whole structure fully visible, anchored at bottom, no shadows, people, animals, text, arrows, or UI. '
jobs=[]
for material,detail in [('kamen','a fortress stone gatehouse side section, massive limestone side piers, thick stone vaulted roof, iron portcullis and exposed side hoisting mechanism; tower thickness extends horizontally along the left-right travel axis'),('drvo','a rustic village timber gatehouse side section, two thick log supports and a small pitched shingle roof, heavy wooden lattice made of square timber beams and side winch'),('rudnik','a mine-exit tunnel side section, heavy timber mine supports and a thick overhead beam, rough stone above, iron portcullis and a side pulley')]:
    opened='prolaz-'+material+'-otvoren';closed='prolaz-'+material+'-zatvoren'
    prompt=style+geometry+' Subject: '+detail+'. OPEN STATE: the entire portcullis is pulled VERTICALLY UP into the vault/under the roof. Only its lower tips may be visible ABOVE the clear opening. The entire central passage below the arch is empty and transparent down to the bottom. No hinged doors. Clear side-on platformer cutaway, no receding interior perspective.'
    jobs.append(dict(id=opened,group=8,kind='portal-open',canvas=[1024,1024],height=1000,alpha=True,orientation='profile',prompt=prompt))
    jobs.append(dict(id=closed,group=8,kind='portal-closed',canvas=[1024,1024],height=1000,alpha=True,orientation='profile',reference='art/world-pack-03/'+opened+'.png',anchorReference=opened,prompt=style+geometry+' Edit the supplied OPEN gatehouse to its CLOSED state. Keep EXACTLY the same side-view structure, frame, stone/log shapes, camera, scale and bottom position. Lower its '+('heavy WOODEN BEAM LATTICE' if material=='drvo' else 'IRON PORTCULLIS')+' VERTICALLY DOWN into the same center opening until its pointed bottom touches the walking line. The bars fill the center opening, with transparent gaps between bars. Do not change or close the tunnel with a wall. No swinging doors. Keep the top hoisting mechanism.'))
jobs.append(dict(id='resetka',group=8,kind='portcullis',canvas=[512,1024],height=1000,alpha=True,orientation='profile-component',prompt=style+'ONE standalone IRON PORTCULLIS only, a tall rectangular medieval iron lattice: strong vertical bars, two horizontal reinforcing rails, pointed spikes at BOTTOM. Front flat sprite suitable for vertical lifting in a side-on gatehouse. NO stone frame, NO wall, NO roof, NO mechanism, NO chain, no other objects. Full grid visible, 512x1024 transparent canvas, grid occupies about 400x950 pixels, bottom tips at bottom of canvas. True transparent gaps between bars and true transparent surroundings. No ground, shadows, text, or glow backdrop.'))
front=style+' FRONT-FACING treasury chamber entrance, entered INTO the screen. Small stone tower facade or corner of fortress wall with one arched ironbound oak door. Entire facade visible on true transparent 1024x1024 canvas, base exactly at bottom, no terrain slab, no people, animals or text. Facade nearly full image height; door is only about FORTY PERCENT of image height (around 410 pixels), small compared with the facade. Rough limestone, brick arch details, carved Serbian ornaments. '
jobs.append(dict(id='ulaz-riznica',group=8,kind='treasury',canvas=[1024,1024],height=1000,alpha=True,orientation='front',prompt=front+'CLOSED state: oak door locked with a HEAVY HORIZONTAL IRON BOLT, deep iron bands. No glowing open entrance, no portcullis.'))
jobs.append(dict(id='ulaz-riznica-otvoren',group=8,kind='treasury',canvas=[1024,1024],height=1000,alpha=True,orientation='front',reference='art/world-pack-03/ulaz-riznica.png',prompt=front+'Edit supplied CLOSED facade to OPEN state. Preserve EXACT facade, silhouette, size, stones, ornaments and door opening position. Door leaves swing inward, iron bolt released. Inside show a small dark treasury chamber illuminated by warm wall torches, amber light spilling through the doorway. The warm interior stays inside the small doorway only. Outer background remains transparent. No other buildings or figures.'))
(R/'plan-g8.json').write_text(json.dumps({'generator':'built-in image_gen','urgent':'DOPUNA-3 before remaining group 7d','jobs':jobs},ensure_ascii=False,indent=2),encoding='utf8')
print('Prepared nine new gate assets; existing art remains untouched.')
